from pathlib import Path

p = Path('lib/main.dart')
s = p.read_text(encoding='utf-8')

if "import 'dart:convert';" not in s:
    s = s.replace("import 'dart:async';\n", "import 'dart:async';\nimport 'dart:convert';\nimport 'dart:io';\n")

s = s.replace("  String _transport = 'Пешком';\n", "  String _transport = 'Пешком';\n  List<_PlaceResult> _placeResults = <_PlaceResult>[];\n  bool _placesLoading = false;\n  String _placeSearchTitle = '';\n")

old = """  void _selectHistory(String value) {\n    _searchController.text = value;\n    setState(() => _searchOpen = false);\n    _showMessage('Поиск: $value');\n  }\n"""
new = """  void _selectHistory(String value) {\n    _searchController.text = value;\n    setState(() => _searchOpen = false);\n    _searchPlaces(value);\n  }\n\n  Future<void> _searchPlaces(String query) async {\n    setState(() {\n      _placesLoading = true;\n      _placeSearchTitle = query;\n    });\n    try {\n      var center = _center;\n      if (_userLocation != null) center = _userLocation!;\n      final uri = Uri.https('nominatim.openstreetmap.org', '/search', {\n        'q': query,\n        'format': 'jsonv2',\n        'limit': '20',\n        'accept-language': 'ru',\n        'addressdetails': '1',\n        'viewbox': '${center.longitude - 0.08},${center.latitude + 0.05},${center.longitude + 0.08},${center.latitude - 0.05}',\n        'bounded': '0',\n      });\n      final client = HttpClient();\n      final request = await client.getUrl(uri);\n      request.headers.set(HttpHeaders.userAgentHeader, 'OurMaps/1.0 (OpenStreetMap search)');\n      final response = await request.close();\n      final body = await response.transform(utf8.decoder).join();\n      client.close();\n      if (response.statusCode < 200 || response.statusCode >= 300) {\n        throw HttpException('HTTP ${response.statusCode}');\n      }\n      final data = jsonDecode(body) as List<dynamic>;\n      final results = data.map((item) => _PlaceResult.fromJson(item as Map<String, dynamic>)).toList();\n      if (!mounted) return;\n      setState(() {\n        _placeResults = results;\n        _placesLoading = false;\n      });\n      _showPlacesSheet();\n    } catch (_) {\n      if (!mounted) return;\n      setState(() => _placesLoading = false);\n      _showMessage('Не удалось найти места. Проверьте интернет.');\n    }\n  }\n\n  void _showPlacesSheet() {\n    showModalBottomSheet<void>(\n      context: context,\n      isScrollControlled: true,\n      showDragHandle: true,\n      builder: (sheetContext) => SizedBox(\n        height: MediaQuery.of(sheetContext).size.height * 0.58,\n        child: Padding(\n          padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Text(_placeSearchTitle, style: Theme.of(context).textTheme.titleLarge),\n              const SizedBox(height: 8),\n              if (_placesLoading) const LinearProgressIndicator(),\n              Expanded(\n                child: _placeResults.isEmpty\n                    ? const Center(child: Text('Ничего не найдено'))\n                    : ListView.separated(\n                        itemCount: _placeResults.length,\n                        separatorBuilder: (_, __) => const Divider(height: 1),\n                        itemBuilder: (_, index) {\n                          final place = _placeResults[index];\n                          return ListTile(\n                            leading: const Icon(Icons.place),\n                            title: Text(place.name, maxLines: 2, overflow: TextOverflow.ellipsis),\n                            subtitle: Text(place.address, maxLines: 2, overflow: TextOverflow.ellipsis),\n                            onTap: () {\n                              Navigator.pop(sheetContext);\n                              final point = LatLng(place.latitude, place.longitude);\n                              _mapController.move(point, 16);\n                              setState(() => _center = point);\n                            },\n                          );\n                        },\n                      ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n"""
if old in s:
    s = s.replace(old, new)

old_chip = """  Widget _quickSearchChip(String label) {\n    return ActionChip(\n      label: Text(label),\n      onPressed: () => _showMessage('Поиск: $label'),\n    );\n  }\n"""
new_chip = """  Widget _quickSearchChip(String label) {\n    return ActionChip(\n      label: Text(label),\n      onPressed: () {\n        final query = _categoryQuery(label);\n        setState(() {\n          _searchOpen = false;\n          _aiOpen = false;\n        });\n        _searchPlaces(query);\n      },\n    );\n  }\n\n  String _categoryQuery(String label) {\n    if (label.contains('Еда') || label.contains('Поесть')) return 'restaurant cafe';\n    if (label.contains('Кофе')) return 'cafe';\n    if (label.contains('Места')) return 'tourism attraction';\n    if (label.contains('Магазины')) return 'shop';\n    if (label.contains('Погулять')) return 'park';\n    if (label.contains('Развлечения')) return 'cinema theatre';\n    if (label.contains('Популярное')) return 'restaurant cafe attraction';\n    return label;\n  }\n"""
if old_chip in s:
    s = s.replace(old_chip, new_chip)

marker = "\nclass ArNavigationPage extends StatefulWidget {\n"
model = """\nclass _PlaceResult {\n  final String name;\n  final String address;\n  final double latitude;\n  final double longitude;\n\n  const _PlaceResult({required this.name, required this.address, required this.latitude, required this.longitude});\n\n  factory _PlaceResult.fromJson(Map<String, dynamic> json) {\n    return _PlaceResult(\n      name: (json['display_name'] as String? ?? 'Место').split(',').first.trim(),\n      address: json['display_name'] as String? ?? '',\n      latitude: double.parse(json['lat'] as String),\n      longitude: double.parse(json['lon'] as String),\n    );\n  }\n}\n\n"""
if model not in s:
    s = s.replace(marker, model + marker)

p.write_text(s, encoding='utf-8')
print('patched live place search')
